test('invoiceTotals calculates subtotal, discount, vat, and total', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'ICON-SET', qty: 5 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.ok(totals.subtotal > 0);
  assert.ok(totals.discount > 0);
  assert.ok(totals.vat > 0);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat);
});

