  assert.equal(totals.subtotal, 17000);
  assert.equal(totals.discount, 2125);
  const lineAmountAfterDiscount = 17000 - 2125;
  const lineVAT = Math.round(lineAmountAfterDiscount * 21 / 100);
  assert.equal(totals.vat, lineVAT);
  assert.equal(totals.total, 17000 - 2125 + lineVAT);
});

